import { makeZip } from './zip.js';

const EXT = { 'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp', 'image/gif': 'gif' };
const extOf = (type, name) => EXT[type] || (name.split('.').pop() || 'img').toLowerCase();

export const CONSENT_STATEMENT =
  'I confirm the person in these photos consents to this edited image being made and shared.';

export const EDIT_NOTE =
  'Edited image: the smiley area of image 2 was replaced with a face cropped from image 3. ' +
  'It is a composite, not an original photograph. Images 2 and 3 are the unaltered files as received.';

export const AI_NOTE =
  'Edited image: the smiley area of image 2 was replaced with a face generated by an AI face-swap model ' +
  '(inswapper_128 with GFPGAN) from image 3. It is a synthetic composite, not an original photograph. ' +
  'Images 2 and 3 are the unaltered files as received.';

// The edited image with the face is ALWAYS entry 1; the two untouched sources follow.
export function buildBundle({ composite, covered, face, regions, note = EDIT_NOTE, now = new Date() }) {
  const enc = new TextEncoder();
  const names = [
    '1_face_restored.jpg',
    `2_covered_original.${extOf(covered.type, covered.name)}`,
    `3_face_source.${extOf(face.type, face.name)}`,
  ];
  const manifest = {
    created: now.toISOString(),
    consent: { confirmed: true, statement: CONSENT_STATEMENT },
    files: [
      { order: 1, role: 'edited: smiley area replaced with the face from image 3', name: names[0], sha256: composite.sha256, width: composite.width, height: composite.height },
      { order: 2, role: 'covered original (unaltered)', name: names[1], sourceName: covered.name, sha256: covered.sha256, width: covered.width, height: covered.height },
      { order: 3, role: 'face source (unaltered)', name: names[2], sourceName: face.name, sha256: face.sha256, width: face.width, height: face.height },
    ],
    regions,
    note,
  };
  const zip = makeZip(
    [
      { name: names[0], data: composite.bytes },
      { name: names[1], data: covered.bytes },
      { name: names[2], data: face.bytes },
      { name: 'manifest.json', data: enc.encode(JSON.stringify(manifest, null, 2)) },
    ],
    now,
  );
  return { zip, manifest, names: [...names, 'manifest.json'] };
}
